"use client"
import { Navigation } from '@/components/navigation';
import { useRouter } from 'next/navigation';
import React, { useEffect } from 'react'
import GlobalApi from '../_utils/GlobalApi';

const MyOrderPage = () => {
    const user = JSON.parse(sessionStorage?.getItem("user") as string);
      const jwt = sessionStorage?.getItem("authToken") as string;
    
    const router = useRouter();

    useEffect(()=>{
        if(!jwt){
            router.replace('/')
        }
        getMyOrder()
    },[])
        const getMyOrder = async()=>{
            const orderedList = await GlobalApi.getOrdersByUserId(user?.id, jwt)
            console.log("ordered items for user",orderedList)

        }

  return (
    <div className='flex  flex-col'>
        <Navigation/>
        <div className='mt-20'>
           <h2 className="p-3 bg-primary text-xl md:text-2xl lg:text-3xl font-bold text-white text-center">
          My Orders
        </h2>

        <div className='my-7 px-5 md:px-10'>
          <h2 className="text-3xl font-bold text-primary">Order History</h2>

          
        </div>
        </div>

    </div>
  )
}

export default MyOrderPage